import assert from 'node:assert/strict'

export const readingExtended=[]
const add=(skill,difficulty,passage,prompt,correct,wrong,explanation)=>readingExtended.push({skill,difficulty,passage,prompt,correct,wrong,explanation})
const central=(d,p,c,w,e)=>add('Central Ideas and Details',d,p,'Which choice best states the main idea of the text?',c,w,e)
const infer=(d,p,c,w,e)=>add('Inferences',d,p,'Which choice is most logically supported by the text?',c,w,e)
const cross=(d,p,task,c,w,e)=>add('Cross-Text Connections',d,p,task,c,w,e)
const support=(d,p,c,w,e)=>add('Command of Evidence (Textual)',d,p,'Which finding, if true, would most directly support the researcher’s hypothesis?',c,w,e)
const weaken=(d,p,c,w,e)=>add('Command of Evidence (Textual)',d,p,'Which finding, if true, would most directly weaken the researcher’s hypothesis?',c,w,e)

central('hard','In a hypothetical study of scientific diagrams, two groups learn the same process from different illustrations. One illustration shows every component in realistic detail; the other omits surface features and emphasizes connections. The detailed version helps participants recognize the equipment in photographs, while the simplified version helps them explain what would happen if a connection were interrupted. The researchers decline to rank either illustration as universally better. Instead, they argue that a representation should be assessed in relation to the question its users need to answer.','Different representations can support different kinds of understanding, making their value dependent on the intended task.',['Simplifying a diagram necessarily makes every aspect of a process easier to learn.','Realistic details prevent viewers from recognizing equipment outside the diagram.','The study establishes that all scientific illustrations should omit connections.'],'The two versions support different outcomes. The researchers’ recommendation concerns matching representation to purpose, not universally favoring realism or simplification.')
central('medium','In this original story, a carpenter is asked to make a second table identical to one she built years earlier. She retrieves her measurements but finds that the available wood bends differently beneath her tools. Matching the measurements exactly would leave the new table less stable. She alters two joints, then places the finished piece beside the first. The customer notices no difference until she explains her changes. She says that repeating a result sometimes requires changing the actions that first produced it.','Achieving a familiar result can require adapting a method to changed materials.',['The carpenter discovers that measurements are never useful in making furniture.','The customer requests a table with a completely different appearance.','The new wood allows the carpenter to avoid making any joints.'],'Different material properties require changed joints to achieve stability and a matching appearance. The measurements remain useful but are not a complete recipe.')
central('hard','A fictional historian studies a commercial ledger whose entries appear to show a sudden increase in sales. An accompanying instruction sheet reveals that the clerk began recording individual purchases where earlier entries combined an entire week’s trade. The historian does not conclude that business stayed constant; total quantities might still have risen. She concludes only that the greater number of entries cannot itself establish growth. Understanding a record, she argues, requires knowing how its units were defined and whether those definitions changed.','Changes in recording practices can complicate conclusions drawn from apparent changes in historical data.',['The ledger proves that sales remained identical in every week.','Individual purchases are inherently less reliable records than weekly totals.','Historical records are useful only when every entry represents one customer.'],'The change in units undermines one inference without settling the actual sales trend. The text emphasizes understanding the recording convention.')
central('medium','In a hypothetical building project, engineers evaluate a shade that reduces indoor temperatures during sunny afternoons. They initially describe the shade as energy-saving. A yearlong assessment shows that, during cold months, the same shade blocks sunlight that would otherwise warm the rooms. Total heating and cooling costs depend on the building’s location and seasonal use. The engineers retain the shade as an option but replace their universal recommendation with guidance about climate, orientation, and the months when each building is occupied.','A design’s overall benefit may depend on conditions omitted from an initial evaluation.',['The shade increases indoor temperatures during sunny afternoons.','The yearlong assessment shows that shades are never useful.','The engineers stop considering heating and cooling costs.'],'The seasonal tradeoff qualifies an initial general recommendation. The shade’s observed afternoon effect remains valid, but its overall value is contextual.')
central('hard','In this original essay, a narrator describes learning a traditional knot from an uncle who never explained it in words. Years later, she writes instructions so others can learn without him. Her first draft records the movements but not the moment when tension must be felt through the cord. Revising it, she realizes that documenting a practice requires discovering which parts she had learned without noticing. The written account does not merely preserve what she already knew consciously; composing it changes her understanding of her own skill.','Explaining a learned practice can reveal knowledge that the practitioner had not previously made explicit.',['The narrator concludes that writing instructions cannot help anyone learn a knot.','The uncle taught the knot entirely through written explanations.','The first draft fully captures every aspect of the practice.'],'The missing sensation prompts reflection on tacit knowledge. Writing changes the narrator’s understanding rather than simply duplicating an already explicit account.')
central('medium','A hypothetical team tests a program that suggests routes through a warehouse. Workers following its suggestions walk shorter distances, but some repeatedly wait at narrow passages because the program directs everyone toward the same shortcuts. The team adds a measure of congestion to the next evaluation. It argues that minimizing each person’s route separately is not sufficient when many people must move through a shared space. A route that is best for one worker alone may contribute to delays when assigned to an entire shift.','Optimizing individual routes can overlook interactions that affect the performance of the whole system.',['Shorter routes always require more walking than longer ones.','The program’s suggestions lengthen every worker’s individual route.','Congestion occurs only when workers ignore the suggested shortcuts.'],'Short individual paths can create shared bottlenecks. The recommendation addresses interaction between simultaneous users, not errors in measuring path length.')
central('hard','A fictional critic examines a set of travel essays written before their author learned the local language. The essays vividly describe unfamiliar sounds and gestures but repeatedly mistake ordinary exchanges for ceremonies. In later essays, accurate explanations replace those misunderstandings, while some sensory detail disappears. The critic values both collections for different reasons. The early essays reveal the traveler’s act of interpretation; the later essays provide better accounts of local practices. Neither collection, she argues, should be treated as an unmediated view from nowhere.','Different kinds of knowledge shape what an observer records and how readers should interpret the resulting account.',['The early essays are more accurate descriptions of local practices than the later essays.','Learning a language prevents all sensory description.','Both collections describe exchanges without any interpretive influence.'],'The critic distinguishes vivid observation from accurate interpretation and values each collection accordingly. Both reflect an observer’s position.')
central('medium','In a hypothetical test of reusable containers, one design survives more washing cycles than another but requires substantially more material to manufacture. Researchers estimate the resources used over many actual uses rather than comparing durability alone. The more durable design becomes preferable only when customers return it often enough. The team therefore recommends pairing its introduction with a reliable return system. A feature that appears beneficial in isolation, the report concludes, may depend on a supporting pattern of use to deliver its expected advantage.','A durable product’s overall resource benefit can depend on how consistently it is reused.',['The less durable container necessarily uses more material to manufacture.','The researchers conclude that return systems have no effect on resource use.','The durable container is preferable regardless of how often it is returned.'],'The tradeoff between manufacturing inputs and repeated use drives the conditional recommendation. Durability alone does not settle overall resource efficiency.')
central('hard','In this original story, an apprentice copies a master calligrapher’s damaged letter exactly, including an accidental break in one stroke. The master asks her to copy it again, this time imagining how the hand had moved before the paper tore. Her second attempt looks less like the surviving mark but follows its motion more closely. She keeps both sheets. One preserves the appearance of a particular object; the other records her attempt to recover a practice from that object’s imperfect evidence.','Copying an artifact’s visible form and reconstructing the action behind it can be different undertakings.',['The apprentice discovers that the original letter was never damaged.','The master asks for two perfectly identical copies of the surviving mark.','The second copy is valuable only because it exactly duplicates the tear.'],'The two sheets distinguish surface resemblance from reconstruction of motion. Neither is described as erasing the distinction or proving the original undamaged.')
central('medium','A hypothetical city introduces a single website for several public services. Residents who already know the name of the office they need complete requests faster. Residents who describe a problem without knowing its administrative category still struggle to select a form. The designers add a problem-based guide alongside the office directory. Their report explains that placing services in one location does not automatically make the underlying organization understandable. A useful entrance must help people translate their needs into the categories the system requires.','Bringing services together does not eliminate the need to help users navigate unfamiliar categories.',['The website makes requests slower for every resident.','The designers remove every office name from the directory.','Residents’ needs are always expressed in the same terms as administrative categories.'],'Different users need different navigational support. The added guide bridges a category gap that consolidation alone leaves unresolved.')
central('hard','A fictional biographer finds that an inventor’s notebooks contain many sketches of devices never built. Earlier accounts treated these as failed projects. The biographer notices that several sketches deliberately combine incompatible parts and appear beside questions about why those combinations would not work. She proposes reading some drawings as tools for investigating limits, rather than as plans awaiting construction. The notebooks may document thinking through impossibility as well as attempts to produce functioning objects; deciding which requires attention to the surrounding notes.','Some unbuilt designs may record exploratory reasoning rather than unsuccessful attempts at construction.',['Every sketch in the notebooks depicts a device that was eventually built.','The notes prove that the inventor never intended to construct anything.','An impossible design cannot contribute to understanding a technical problem.'],'The incompatible combinations and questions support a new interpretation of some sketches. The qualification some avoids reclassifying every drawing.')
central('medium','In a hypothetical study, people use two interfaces to compare insurance policies. One presents all details at once; the other reveals information in stages. The staged version feels easier initially, but some users fail to discover exclusions hidden in later screens. Researchers add a test requiring users to identify which policy would cover a particular event. They argue that a pleasant first impression and an informed decision are related but distinct outcomes, both of which should be considered when evaluating the interface.','An interface’s apparent ease should be evaluated alongside whether it supports informed choices.',['The staged interface makes every exclusion visible on its first screen.','Users’ first impressions always predict accurate decisions.','The researchers stop measuring whether users understand policy coverage.'],'The missing exclusions expose a gap between initial ease and decision quality. The report proposes measuring both rather than replacing understanding with preference.')
central('hard','In this original poem, a speaker visits a workshop after its owner has retired.\n\nThe hammer hangs where daylight ends;\nthe bench remembers every cut.\nI lift a tool and set it down,\nthen leave the narrow window shut.\nNo hand has moved the things for weeks,\nyet nothing here seems still to me:\nthe room keeps giving back the work\nI came expecting not to see.\n\nThe speaker finds activity perceptible through traces even in the absence of someone actively working.','Material traces can make past activity feel present in an apparently inactive place.',['The speaker repairs the window and begins working at the bench.','The poem argues that the room contains no evidence of its former use.','The retired owner returns and explains every mark on the bench.'],'The tools and cuts evoke work despite the owner’s absence. The poem’s stillness is complicated by memory and traces, not a literal return to work.')
central('medium','A hypothetical report compares two emergency supply plans. One stores everything in a central depot, reducing ordinary storage costs. The other distributes smaller stocks across several sites, making supplies easier to reach if a road closes. The report does not declare a single winner. It asks planners to evaluate expected disruptions, travel routes, and the value of maintaining access during rare events. Lower routine cost and resilience under unusual conditions, it argues, are different advantages that a decision should weigh explicitly.','Supply planning involves weighing routine efficiency against access under possible disruptions.',['The distributed plan has lower ordinary storage costs in the report.','A central depot guarantees access regardless of road closures.','The report concludes that rare disruptions should never influence planning.'],'The two plans offer different benefits under different circumstances. The main claim concerns an explicit tradeoff rather than one universally dominant plan.')
central('hard','A fictional researcher studies corrections in a composer’s draft. A crossed-out passage sounds more elaborate than its replacement, so an earlier critic described the revision as a loss of ambition. The researcher reads the surrounding pages and finds that the simpler passage allows a previously hidden melody to remain audible. She proposes assessing a revision by its effect on the whole work, rather than assuming that greater local complexity always represents greater artistic achievement. The apparent subtraction can serve a larger compositional purpose.','A simpler local revision can support a broader artistic goal that isolated comparison would miss.',['The replacement contains more notes than the crossed-out passage.','The researcher proves that elaborate music has no artistic value.','The revision removes the previously hidden melody from the work.'],'The whole-work role explains why simplification can be purposeful. The passage does not equate all complexity with failure or reject ambition.')
central('medium','In a hypothetical learning program, participants choose how often to receive progress notifications. Many initially request frequent messages, then reduce the frequency after several weeks. Interviews show that reminders help establish a routine early but later interrupt work participants already perform regularly. The designers introduce settings that can change over time. They argue that preferences recorded at the beginning of a program need not remain suitable after users gain experience and their behavior changes. A helpful design should accommodate that development.','Support that is useful at an early stage may need to change as users develop a routine.',['Participants request progressively more notifications throughout the program.','The interviews show that reminders never help establish routines.','The designers decide that initial preferences must remain permanently fixed.'],'Changing needs explain both the reduced notification requests and adaptable settings. The passage describes development, not a universal rejection of reminders.')

infer('hard','A hypothetical researcher evaluates a method for detecting equipment faults using a collection containing equal numbers of faulty and functioning machines. The method identifies most faults but also flags some functioning machines. A factory wants to use it where faults are rare. The researcher notes that detection accuracy for each type of machine could remain unchanged while the composition of flagged machines changes substantially. She recommends testing the proportion of actual faults among alerts under the factory’s conditions before estimating the workload for inspectors.','A test set’s mix of faulty and functioning machines can affect how informative an alert appears.',['The factory must contain equal numbers of faulty and functioning machines.','An unchanged fault-detection rate guarantees the same proportion of genuine faults among alerts.','The method cannot flag a functioning machine.'],'The proportion among alerts depends on the prevalence of actual faults as well as each conditional error rate. The balanced test mix may not reflect factory alert composition.')
infer('medium','In this original story, a librarian asks volunteers to arrange donated books by subject. One volunteer puts a gardening manual beside a book of family letters because both contain pressed flowers. The librarian begins to correct her, then asks her to explain. By evening they have made two displays: one organized by content and another by what previous readers left between the pages. The librarian keeps the original subject labels in a drawer for the following week’s regular shelving.','The librarian recognizes a temporary alternative way of interpreting the books without abandoning the ordinary classification.',['The volunteer follows the original subject instruction exactly.','The librarian decides that subject labels can never be useful again.','Every donated book contains a pressed flower.'],'The second display legitimizes the volunteer’s connection, while keeping the labels for regular shelving shows that subject classification retains a role.')
infer('hard','In a hypothetical trial, a new surface coating prevents a stain from appearing during a short exposure. A longer exposure eventually produces the same stain as on an untreated surface, though it appears later. The manufacturer describes the coating as stain-proof. The researchers distinguish preventing the process entirely from delaying a visible result and note that the intended cleaning schedule may determine whether the delay is useful in practice. They have not tested other substances that could cause staining.','The coating may have practical value even though the claim of complete stain prevention is unsupported.',['The coating delays stains from every possible substance.','The long exposure proves that the short-exposure observations were fabricated.','A delayed visible result is identical to preventing staining permanently.'],'Delay can be useful relative to cleaning intervals, but it does not establish permanent prevention or performance against untested substances.')
infer('medium','In a fictional interview project, participants are first asked to describe their working day in their own words. Later they answer a standard list of questions. Several subjects mention cooperation spontaneously but do not discuss it in the structured portion because none of the questions addresses it. A researcher who reads only the structured answers concludes that cooperation is unimportant to participants. The project director asks that the earlier accounts be considered before making that judgment.','The structured questions may omit a topic that participants themselves consider relevant.',['Participants never mention cooperation in any part of the interviews.','The spontaneous accounts prove cooperation is the only important feature of work.','Every structured question was answered dishonestly.'],'Spontaneous mention supplies evidence the structured list does not capture. Omission from that portion need not indicate lack of importance or dishonesty.')
infer('hard','A hypothetical forecasting tool predicts demand accurately when the price of a service remains near its historical range. A company proposes using the tool to predict demand after a very large price increase. The training records contain no comparable changes, and the model treats the relationship between price and demand as unchanged across all prices. The developers recommend a limited pilot before relying on its forecast for the proposed increase, even though its historical prediction errors are small.','Strong performance within the observed range does not directly verify the model’s assumption outside that range.',['Small historical errors prove the model will be equally accurate at every price.','The training records already contain many comparable price increases.','The developers know that demand will remain exactly constant.'],'The recommendation concerns extrapolation beyond observed changes. Historical fit alone does not validate an assumed relationship in a new price range.')
infer('medium','In this original poem, a speaker visits a childhood home that has been rebuilt.\n\nThey moved the door, replaced the stair,\nand took the pear tree from the yard.\nI found no mark I meant to find,\nno name upon the paving stone.\nThen someone laughed beyond the wall,\nand I turned first toward the place\nwhere once the kitchen window was,\nbefore I knew the sound was strange.\n\nThe speaker’s bodily response precedes recognition that the present setting and people have changed.','A remembered spatial habit can persist after the physical features that formed it have disappeared.',['The rebuilt house retains every original feature.','The laughter comes from someone the speaker immediately recognizes.','The speaker deliberately reenacts a response after analyzing the sound.'],'The automatic turn toward the former window shows persistence of habit despite reconstruction. Recognition comes afterward, and the sound is unfamiliar.')
infer('hard','A hypothetical study finds that learners who explain a solution perform better on a later test than learners who merely reread it. The explanation group also spends longer with the material. The authors acknowledge that their design does not separate the benefit of explaining from the benefit of additional study time. A school cites the study as proof that explaining is better than any equally long alternative. The researchers propose a comparison in which time is held constant before endorsing that conclusion.','The reported result leaves open whether extra time accounts for some or all of the advantage.',['The study demonstrates that explanation has no possible benefit.','The groups spent exactly equal amounts of time in the original study.','The proposed time-matched comparison has already confirmed the school’s claim.'],'Because method and time differ together, the result cannot isolate explanation. This uncertainty is not evidence that explanation is ineffective.')
infer('medium','A fictional theater company advertises a performance as accessible because it provides a written transcript afterward. A deaf audience member explains that the transcript helps review the dialogue but does not allow her to follow its timing during the performance. The company begins testing live captions while keeping the transcript available. Its director notes that the two formats support different moments of participation, and that the later document does not replace access to the unfolding event itself.','Providing information afterward need not give someone the same access as providing it during an event.',['The audience member finds the transcript entirely useless.','The company removes the transcript when it starts caption testing.','Live captions and later transcripts necessarily serve identical purposes.'],'Review and real-time participation are distinct uses. The text retains the transcript’s value while identifying a need it does not satisfy.')
infer('hard','In a hypothetical comparison, a machine performs a repetitive task faster than a worker when every input is correctly arranged. The worker performs better when inputs arrive in unexpected positions because she reorients them before proceeding. The evaluation report includes preparation time only for the worker; an assistant’s time arranging the machine’s inputs is excluded. A reviewer asks for an assessment covering the entire workflow rather than the central action alone.','The reported speed comparison may understate the human work needed to make the machine’s performance possible.',['The assistant performs no work before the machine runs.','The machine handles unexpected input positions better than the worker.','The reviewer has established that the machine must be slower in every complete workflow.'],'The excluded preparation contributes to machine operation. Counting it may change the comparison, but the passage gives no totals proving a universal ranking.')
infer('medium','In this original story, a boy asks his grandmother why she keeps a recipe whose quantities are crossed out. She says she wrote it when she cooked for twelve people, then changed it for six, then two. He offers to copy the final version neatly. She asks him to leave the crossings visible and shows him which change followed each departure from the household. He puts the recipe back without replacing the sheet.','The grandmother values the recipe partly as a record of changes in the household.',['The recipe’s final quantities are impossible to read.','The grandmother has forgotten why any quantities were changed.','The boy destroys the sheet after copying it.'],'Her explanation ties visible revisions to departures and her request preserves that history. Practical readability is not the only value of the sheet.')
infer('hard','A hypothetical survey asks residents whether a new park is easy to reach. Most respondents who currently visit it say yes. People who stopped visiting because a bus route was removed are not included, since interviewers recruit only inside the park. The report accurately summarizes the visitors’ answers. A planner nevertheless questions using the percentage to describe access for all residents. She requests responses from people who do not currently come to the site, including former visitors.','An accurate summary of current users can still omit people whose access difficulties prevent their inclusion.',['The visitors’ answers must all be false.','Removing a bus route necessarily improves access for every resident.','The original sample includes all former visitors.'],'The concern is coverage, not inaccurate transcription of answers. Recruiting at the site can exclude those kept away by the very difficulty being measured.')
infer('medium','A fictional critic reads two editions of a memoir. The second omits several descriptions of the author’s early embarrassment but retains the same sequence of public events. The author calls the revision a correction of tone rather than fact. The critic notes that a reader could accept the chronology in both editions while gaining different impressions of the narrator’s younger self. She therefore compares not only what events remain but also how the narrator positions herself in relation to them.','An unchanged chronology does not guarantee an unchanged portrayal of the narrator.',['The second edition replaces every public event with a different one.','The critic concludes that both chronologies are necessarily false.','Descriptions of emotion cannot affect a reader’s impression.'],'The omitted embarrassment changes self-presentation without changing event order. The inference separates chronology from interpretive portrayal.')
infer('hard','A hypothetical laboratory develops a detector that responds to a substance only above a certain concentration. Samples from an early stage of a process produce no response; later samples do. A report concludes that the substance first appears at the later stage. The detector’s developers caution that an earlier amount below its detection threshold would also produce no response. They recommend a more sensitive measurement before treating the first positive result as the moment the substance began to exist.','A first detectable appearance may occur after the substance is already present at a lower concentration.',['The substance certainly existed at the same concentration in every sample.','The detector responds equally at all concentrations.','The developers conclude that every positive result is false.'],'A threshold separates detectable from undetectable quantities, not necessarily presence from absence. The proposed further measurement addresses that distinction.')
infer('medium','In this original story, a ferry operator knows the crossing so well that she seldom looks at the shore. Asked to teach a replacement, she begins naming landmarks and realizes that several familiar reference points have disappeared behind new buildings. She can still navigate by subtler changes in the current, but her spoken instructions describe the landscape as she first learned it. She spends the next week revising the instructions while making the crossings with her trainee.','Her ability to perform the task has adapted in ways her explicit description has not kept up with.',['She has lost the ability to make the crossing.','All of the landmarks remain visible in their original positions.','Her trainee has already memorized every change in the current.'],'Continued successful navigation contrasts with outdated verbal landmarks. Teaching exposes a gap between current practical skill and its explicit account.')
infer('hard','A hypothetical report compares two routes through a regional delivery network. One route is faster for ordinary loads but cannot carry unusually tall packages. The other is slower but accepts every package size in the company’s current inventory. The report lists average journey time only for packages that each route actually carried. A manager proposes sending every package by the route with the lower listed average, without checking package dimensions. The analysts recommend separating eligibility from travel-time comparisons.','The faster listed route may not be available for some packages covered by the manager’s proposal.',['The slower route cannot carry any tall packages.','Every package in the inventory has identical dimensions.','The listed average proves that the faster route can carry all package sizes.'],'The eligibility restriction persists regardless of the average among eligible loads. The proposal extends the route beyond its stated capability.')
infer('medium','In this original poem, a speaker describes an unused ticket.\n\nThe date has passed. The ink is clear.\nNo train will take this paper now.\nI keep it where the letters lie,\nnot for a journey still to come,\nbut for the hour I had believed\nthat going was a thing I chose.\n\nThe ticket no longer grants passage, yet the speaker places it with personal correspondence rather than discarding it among expired papers. Its value is connected to the remembered possibility of leaving.','The speaker preserves the ticket as evidence of a past expectation rather than a usable travel document.',['The ticket remains valid for an upcoming train.','The speaker keeps it only because the ink is illegible.','The speaker expects the expired date to change.'],'The poem explicitly distinguishes future travel from remembrance of an earlier belief. The ticket’s personal value survives its practical expiration.')

support('hard','In a hypothetical study of insect navigation, a researcher hypothesizes that insects locate a shelter by the geometric arrangement of nearby objects rather than by the objects’ individual colors. She proposes testing the same trained insects after changing one feature at a time. The shelter itself can be moved without adding a visible marker. To distinguish the explanations, the tests must separate the arrangement that was associated with shelter from the particular colors that originally occupied its positions, while keeping other cues as similar as possible.','After the colors are exchanged among objects, insects search at the position predicted by the original arrangement rather than at the position predicted by the original colors.',['Insects spend equal time resting before each trial.','The objects can be repainted without changing their sizes.','Insects sometimes enter the shelter during training.'],'Following arrangement when color and arrangement predictions conflict directly supports the proposed cue. The other findings concern feasibility or basic behavior, not the competing explanations.')
support('medium','A hypothetical researcher studies why some people understand assembly instructions better when each step includes a picture. She hypothesizes that the pictures help users identify how components should be oriented, rather than merely making the page more appealing. She compares otherwise identical instructions and plans a practical test that separately records orientation errors and other errors. The components have similar shapes but must face particular directions. A favorable overall rating alone would not distinguish her explanation from an effect of visual attractiveness.','Adding orientation diagrams reduces errors in which components face the wrong direction, even when page-attractiveness ratings remain similar.',['Participants prefer a colorful cover to a plain one.','The instructions contain the same number of steps in both versions.','Some components are made from the same material.'],'The outcome is specific to the proposed orientation mechanism and is separated from attractiveness. Equal step counts alone do not show the predicted effect.')
support('hard','A hypothetical researcher hypothesizes that a decline in a machine’s accuracy comes from changes in the sensor’s calibration rather than deterioration of the object being measured. The machine repeatedly measures the same stable reference object, and its readings drift over time. The researcher can recalibrate the sensor without replacing either the machine’s other components or the reference object. A useful test should show whether correcting the proposed source of error reverses the drift while the alternative source remains unchanged.','Recalibrating the sensor restores the expected readings for the unchanged reference object.',['The machine’s casing becomes warmer during use.','A different machine has a different display size.','The reference object remains in the same room throughout the study.'],'Restoration after the specific calibration intervention supports sensor drift as the cause. The unchanged object helps distinguish it from deterioration.')
support('medium','In a fictional study of reading, a researcher hypothesizes that headings help readers organize information rather than simply reminding them of individual terms. Participants read passages containing the same facts, with or without headings. The researcher distinguishes memory for isolated details from understanding relationships among sections. She predicts a benefit on tasks that require locating and connecting related claims, even when participants remember comparable numbers of individual facts. A test of the proposed explanation therefore needs more than a count of recalled words.','Readers given headings connect related claims from different sections more accurately, despite recalling about the same number of isolated facts as other readers.',['Readers in both groups recognize the passage’s title.','The headings use a slightly larger font than the main text.','Participants report having read books before the experiment.'],'The selective benefit for organization matches the hypothesis while isolated recall is held similar. The other findings do not measure relational understanding.')
support('hard','A hypothetical researcher proposes that a protective fabric works by trapping a layer of still air, not solely because its fibers resist heat transfer. The fabric can be tested in its usual form and in a compressed form made of the same fibers. Compression greatly reduces the spaces that can hold air. The researcher controls the amount of fiber and tests both forms under comparable temperature conditions. She seeks a result that links the spaces between fibers to insulation performance rather than merely showing that fabric can insulate.','The compressed fabric loses substantially more insulating ability than would be expected from the unchanged amount of fiber alone.',['Both forms are manufactured from the same batch of fibers.','The fabric can be folded before testing.','The temperature instruments display values in the same units.'],'Reduced performance when air spaces are collapsed supports their role. Shared materials and units are controls, not themselves evidence for the proposed mechanism.')
support('medium','A fictional researcher hypothesizes that a neighborhood notice board draws participation because residents can see that other residents have contributed. She distinguishes this social cue from the amount of useful information posted. Two boards display identical announcements in equally visible locations. On one, contributor names are shown; on the other, they are omitted. The researcher wants evidence that identifiable local participation influences whether a reader chooses to add an announcement, rather than assuming every difference in use comes from informational content.','Residents who see familiar contributor names are more likely to add notices than residents seeing the identical unsigned announcements.',['The two boards have the same dimensions.','Some announcements mention events occurring next month.','Residents can read both boards without assistance.'],'Holding announcements similar while varying contributor visibility directly tests the social cue. Dimensions and readability alone do not show the behavioral influence.')
support('hard','A hypothetical researcher suspects that a species appears rare in a visual survey because its active period has shifted, rather than because its population has sharply declined. The traditional survey always takes place at midday. She proposes repeating observations at several times while maintaining comparable locations and observation effort. To favor her explanation, the new observations must indicate a redistribution of detectable activity over the day, not merely show that the species can occasionally be found outside the old survey period.','Counts fall at midday but rise by a similar amount at another time, leaving the total across equally sampled periods roughly unchanged.',['The species is photographed once at sunset.','The survey team uses the same notebooks as before.','Midday temperatures can be measured at the survey sites.'],'A shift with a stable overall count fits changed timing more directly than a single isolated sighting. Equal observation effort makes the period comparison meaningful.')
support('medium','A hypothetical researcher argues that a reusable checklist helps workers detect omissions while completing a task, rather than teaching them information they did not previously know. She first verifies that participants can name every required step without the checklist. During the task, interruptions sometimes cause a step to be skipped. The researcher predicts that making the checklist available will reduce these missed steps even among participants whose knowledge is already complete. Her design separates having the information from reliably applying it under interruption.','Knowledgeable workers randomly assigned a checklist omit fewer steps during interruptions than equally knowledgeable workers without one.',['Some workers prefer a checklist printed on thick paper.','The checklist lists all the required steps.','Workers can pronounce the name of each tool used.'],'The comparison tests execution support among people already shown to know the steps. Merely listing the steps does not demonstrate an effect on omissions.')

weaken('hard','A hypothetical researcher hypothesizes that a bright display improves performance solely by making symbols easier to distinguish. Participants perform better with the bright display than with a dim one. However, the bright condition also includes a sound at the beginning of each task. The researcher argues that the sound is irrelevant and attributes the entire benefit to visual clarity. To assess that exclusive explanation, another team separately varies brightness and the sound while keeping symbols and task difficulty the same across conditions.','The sound improves performance at either brightness, while changing brightness without changing the sound produces no improvement.',['Participants can see symbols in the bright condition.','The task uses the same symbols in both conditions.','The bright display uses more electricity than the dim display.'],'The independent sound effect and absent brightness effect contradict an explanation assigning the entire benefit to visual clarity. Visibility alone does not distinguish causes.')
weaken('medium','A fictional researcher hypothesizes that readers prefer a particular edition of a story because its paragraphs are shorter. In the original comparison, that edition also uses a larger, more familiar typeface. She claims the paragraph length alone explains the preference and plans to recommend shortening paragraphs in every edition. A follow-up study compares paragraph lengths while holding typeface constant and also compares typefaces while holding paragraph length constant. The story’s wording and order remain unchanged in all versions.','Readers’ preferences track the typeface but do not change when paragraph length changes within either typeface.',['The story has the same ending in every version.','Some readers finish the story faster than others.','The shorter-paragraph edition contains several pages.'],'The controlled pattern attributes preference to the alternative feature and finds no paragraph-length effect. The unchanged ending is a control, not a contradiction of the hypothesis.')
weaken('hard','A hypothetical researcher attributes declining water readings in a storage tank entirely to a leak. The readings come from a sensor newly installed at the start of the decline. The researcher notes that the tank has no scheduled withdrawals during the measured period. Another team checks the actual water quantity independently and tests the sensor against known volumes. The proposed leak should reduce the independently measured quantity as well as the sensor’s displayed estimate, if it is the sole cause of the reported change.','Independent measurements show a stable water quantity, while the new sensor reports progressively lower values for a fixed known volume.',['The sensor displays measurements at regular intervals.','No scheduled withdrawals occur during the observation period.','The tank is located outside the laboratory.'],'Stable actual quantity and drifting measurements point to sensor error instead of the proposed leak. The absence of scheduled withdrawals does not eliminate measurement error.')
weaken('medium','A fictional researcher proposes that a decline in attendance at a discussion group results solely from loss of interest in its topic. During the same period, meetings move from evenings to weekday afternoons. The group continues to draw positive topic ratings from people who attend. To test the scheduling alternative, organizers offer an additional evening session with the same topic, speaker, and publicity. The researcher predicts that restoring the old time will not bring back former participants if interest alone explains their absence.','Many former participants return to the evening session and report that work prevented them from attending the afternoon meetings.',['The afternoon meetings take place in the same room.','The speaker’s biography appears on the announcement.','Some current attendees still rate the topic positively.'],'Return under the restored schedule, accompanied by a relevant access explanation, directly challenges loss of interest as the sole cause. Ratings by current attendees alone are less direct.')
weaken('hard','A hypothetical researcher hypothesizes that a plant extract slows bacterial growth because of a particular dissolved compound. The extraction procedure also makes the liquid more acidic, and the researcher has not separated these features. A second team compares the extract with a compound-free liquid matched in acidity and with extract whose acidity has been neutralized. All other growth conditions are held similar. The proposed compound explanation predicts an effect beyond what acidity alone produces, provided the neutralization does not alter the compound.','Acid-matched liquid without the compound slows growth equally, while neutralized extract containing the unchanged compound does not.',['The extract is stored in labeled containers.','The bacteria grow in an untreated comparison liquid.','The dissolved compound can be detected in the original extract.'],'The controlled result tracks acidity rather than the unchanged compound. Mere presence of the compound does not establish its causal role.')
weaken('medium','A fictional researcher claims that a new suggestion box reveals a genuine increase in workplace problems because it collects more complaints than the old process. The box allows anonymous submissions, whereas the old process required a signed appointment with a supervisor. The researcher treats the reporting change as irrelevant. A follow-up project independently tracks the problems mentioned and asks employees how they previously handled the same difficulties. Evidence that more existing problems are now reported would challenge the claim that the larger count proves worsening conditions.','Independent problem rates remain stable, while employees report using the new box for difficulties they previously kept unreported.',['The new box has a different shape from the old appointment desk.','Employees can submit more than one complaint.','The researcher counts the submissions each week.'],'Stable independent rates plus newly reported old problems supports a reporting change rather than a genuine increase. Counting submissions alone cannot distinguish those possibilities.')
weaken('hard','A hypothetical researcher proposes that animals choose a marked feeding station because they recognize a particular geometric symbol. In training, that symbol is always attached to the same physical container, which may retain an odor. The researcher claims the visual symbol alone controls choice. Another team cleans both containers, then exchanges the symbols while preserving the containers’ other identifying features. A separate trial exchanges only the containers’ positions. These comparisons are intended to distinguish symbol, container, and location cues rather than simply repeat the original arrangement.','Animals continue choosing the original container after the symbols are exchanged, even when that container is moved to a different position.',['Animals approach the marked station during the original training.','The symbols can be seen under the test lighting.','The two containers have the same capacity.'],'Choice follows container identity against both changed symbol and changed location. That challenges exclusive control by the visual symbol without uniquely identifying which remaining container feature matters.')
weaken('medium','A fictional researcher hypothesizes that a museum’s longer average visit duration reflects increased engagement with exhibits. A renovation occurred before the increase, and the researcher assumes the added time is spent looking at displays. The new layout also places the exit beyond a long corridor containing no exhibits. The museum records total entry-to-exit time but initially does not separate viewing from movement. A follow-up tracks how visitors allocate their time while preserving the same definition of a visit used in the earlier records.','Exhibit-viewing time is unchanged, and the entire increase in visit duration is accounted for by walking through the new exit corridor.',['The renovation changes the color of the entrance walls.','The museum continues to record entry and exit times.','Some visitors arrive in groups rather than alone.'],'The additional time is attributed to nonviewing movement rather than greater engagement. The result directly addresses the interpretation of the aggregate duration.')

cross('hard','Text 1\nIn a fictional essay, a designer argues that removing every optional setting is the best way to make a tool approachable. Users, she says, should not have to understand choices before they can begin working.\n\nText 2\nAnother designer agrees that a crowded first screen can discourage beginners. He recommends a simple initial setup with additional settings available later, noting that experienced users may need options that beginners do not yet understand. Simplicity at entry, he argues, need not require permanent limitation.','Which position would both designers most likely endorse?','An initial interface that demands understanding many settings can create difficulty for beginners.',['Every optional setting should be permanently removed.','Beginners and experienced users necessarily have identical needs.','The most approachable initial screen always displays every available option.'],'Both recognize a barrier from excessive initial choices. They differ over whether options should be eliminated or made available later.')
cross('medium','Text 1\nA fictional historian describes a village’s surviving festival programs as a complete account of local music. Since they list formal concerts, she concludes that musical life centered entirely on scheduled public performances.\n\nText 2\nAnother historian studies household diaries and finds repeated descriptions of informal singing while people cooked or repaired equipment. Festival programs, he notes, were designed to announce public events, not to inventory every setting in which music occurred. He therefore treats them as evidence for one part of musical life.','How does Text 2 qualify Text 1’s conclusion?','It identifies musical activity outside the scope of the source that Text 1 treats as comprehensive.',['It proves the listed concerts never took place.','It shows that festival programs describe household cooking in detail.','It argues that diaries cannot provide information about informal music.'],'The diaries reveal a category the programs were not intended to record. That challenges comprehensiveness without invalidating the concert listings.')
cross('hard','Text 1\nIn a hypothetical debate, an engineer argues that a repair method should be judged by the strength of a joint immediately after repair. The method producing the strongest initial bond should always be preferred.\n\nText 2\nA second engineer tests repaired joints under repeated bending. Some initially strong joints become brittle, while others retain moderate strength for much longer. She recommends choosing a method in relation to the expected pattern of use and the acceptable risk of later failure.','What assumption in Text 1 does Text 2 most directly challenge?','That initial strength is sufficient to establish the preferable repair method for every use',['That repaired joints can be tested for strength','That some joints begin stronger than others','That bending places stress on a joint'],'Long-term behavior can reverse a ranking based only on immediate strength. The second engineer does not deny that initial strength is measurable or variable.')
cross('medium','Text 1\nA fictional critic describes a story’s final page as indecisive because it does not reveal whether the main character accepts an offer to leave home. The critic regards that unresolved choice as a failure to complete the plot.\n\nText 2\nAnother critic notes that the final page shows the character asking questions she had previously been afraid to consider. For this critic, the story’s central change concerns her ability to imagine alternatives; whether she eventually departs is a separate question.','What is the main source of the critics’ disagreement?','They identify different developments as the story’s central outcome.',['They disagree about whether the final page states a departure decision.','They have read endings in which different characters appear.','They both consider the character’s new questions irrelevant.'],'Both accept the unresolved decision. They differ over whether plot completion requires that decision or can consist in a changed capacity to consider choices.')
cross('hard','Text 1\nA hypothetical researcher finds that people who use a financial planning app save more money than nonusers. She recommends the app as the cause of the difference, noting that the sample includes thousands of people.\n\nText 2\nAnother researcher observes that users chose the app themselves. People already determined to save may be more likely to install it. A large sample can describe an association precisely, he argues, while still leaving that alternative explanation unresolved.','Which study would most directly address the concern in Text 2?','A randomized comparison of app access among people recruited under the same eligibility rules',['A larger survey using the same self-selected user groups','A count of how many features the app offers','Interviews only with the users who saved the most'],'Random assignment addresses systematic selection into access. More observational participants do not by themselves separate prior motivation from app effects.')
cross('medium','Text 1\nA fictional curator favors restoring an old instrument to playing condition, arguing that hearing it is essential to understanding how it once functioned. An object that remains silent leaves an important part of its history inaccessible.\n\nText 2\nAnother curator notes that replacing fragile original components would erase evidence about early construction. She proposes keeping the instrument intact and building a playable replica, while clearly labeling which sounds come from the reconstruction rather than from the surviving object.','On which point would both curators most likely agree?','Sound can contribute to understanding the instrument’s historical function.',['Original components should always be replaced.','A replica and the surviving object provide identical kinds of evidence.','The instrument should never be heard in any reconstructed form.'],'Both seek access to sound; the second proposes a replica to balance that aim with material preservation. They disagree over how to obtain it.')
cross('hard','Text 1\nIn a hypothetical report, a planner argues that an empty seat on a bus represents wasted capacity. She recommends reducing service whenever average occupancy is low, so that nearly every seat is usually filled.\n\nText 2\nA second planner notes that spare capacity allows riders to board during unexpected demand surges. She also distinguishes routes serving essential destinations from routes with frequent alternatives. Average occupancy, she argues, does not by itself measure the value of keeping service available.','How would the second planner most likely respond to the first?','A seat’s being unused on average does not establish that maintaining its availability has no value.',['Every bus should have the maximum possible number of empty seats.','Average occupancy is impossible to calculate.','Unexpected demand can occur only on routes that are already full.'],'Spare capacity and essential access supply benefits the first measure omits. The response qualifies occupancy-based decisions without universally favoring empty service.')
cross('medium','Text 1\nA fictional reviewer praises a biography for arranging every event in strict chronological order. She considers this arrangement the most transparent way to show how the subject’s ideas developed.\n\nText 2\nAnother reviewer notes that the subject returned to the same problem at widely separated times. A thematic arrangement could place those revisions together, making continuities and changes easier to compare. He acknowledges that such an arrangement must still make the dates clear to avoid suggesting that distant events were simultaneous.','What does Text 2 suggest about chronological arrangement?','It preserves temporal sequence but may separate material that is useful to compare directly.',['It necessarily falsifies the dates of all events.','It is the only arrangement that can show intellectual development.','It places every discussion of one problem together regardless of date.'],'The second reviewer values dates but identifies a comparative advantage of themes. This is a tradeoff rather than a claim that chronology is inherently false.')
cross('hard','Text 1\nA hypothetical researcher argues that a model is valuable only if each internal variable corresponds to a physical feature of the process being modeled. Accurate predictions without that correspondence, she says, cannot count as understanding.\n\nText 2\nAnother researcher distinguishes explaining mechanisms from guiding decisions. A model may fail to reveal why a process occurs yet still help users choose when to intervene, if its predictions are reliable in the relevant setting. She recommends stating that limited purpose explicitly.','What distinction is central to Text 2’s response?','The distinction between explaining a mechanism and providing useful predictive guidance',['The distinction between models with numerical outputs and models with written titles','The distinction between two physical features represented by one internal variable','The distinction between accurate predictions and predictions already known to be false'],'The second researcher grants limited mechanistic insight while defending decision value. Her argument concerns different purposes for a model.')
cross('medium','Text 1\nA fictional teacher recommends giving students a completed solution before they attempt a problem. Seeing a clear method first, she argues, prevents confusion and makes later practice more efficient.\n\nText 2\nAnother teacher agrees that examples can be helpful but sometimes asks students to attempt a problem before seeing one. Their initial difficulties reveal which features require explanation, and the later example can answer questions they now recognize. He does not claim that unsupported struggle is always productive.','How do the teachers’ views primarily differ?','They emphasize different possible benefits of the order in which attempts and examples occur.',['One believes examples can help, while the other rejects every use of examples.','They disagree about whether students can encounter difficulty.','Both insist on giving a completed solution before every attempt.'],'The second view changes sequencing while retaining examples and qualifications. The disagreement is not a wholesale rejection of worked solutions.')
cross('hard','Text 1\nIn a hypothetical discussion, an analyst treats a stable average income as evidence that a community’s economic circumstances did not change. She assumes that any important change would appear in the average.\n\nText 2\nA second analyst notes that increases for some households can offset decreases for others. He recommends examining the distribution and identifying which households gained or lost before characterizing the community as unchanged. A stable aggregate, he argues, can coexist with substantial changes in individual circumstances.','What does Text 2 identify as a limitation of Text 1’s reasoning?','An unchanged average can conceal offsetting changes within the population.',['The average cannot be computed when households have different incomes.','A stable average proves that every household lost income.','Important economic changes always move every household in the same direction.'],'The second analyst supplies a mechanism for hidden individual change. He does not infer a particular direction for every household from the aggregate alone.')
cross('medium','Text 1\nA fictional essayist calls an old recording an exact preservation of a performance because the same sounds can be replayed years later. She describes listening as returning to the original occasion.\n\nText 2\nAnother essayist values the preserved sound but notes that a recording does not reproduce the listeners’ knowledge, the room’s social setting, or expectations on that evening. Replaying the sound creates a new encounter with a surviving trace rather than transporting the present audience back unchanged.','Which statement best captures the disagreement?','Whether preserving audible information also preserves the full experience of its original occasion',['Whether a recording can retain any audible information','Whether the original performance occurred in the past','Whether later listeners can hear the recording at all'],'The second essayist accepts preserved sound but distinguishes it from the entire situated experience. The first equates playback with return more broadly.')
cross('hard','Text 1\nA hypothetical researcher credits a new scheduling system with reducing missed appointments, based on a comparison before and after its introduction. The system is the most visible change in the office during that period.\n\nText 2\nAnother researcher notes that the office also began sending free transport vouchers. She proposes comparing groups with and without the scheduling system while keeping voucher access the same. Visibility of one change, she argues, does not distinguish its contribution from that of a simultaneous change.','What is the purpose of the comparison proposed in Text 2?','To separate the scheduling system’s contribution from the effect of transport assistance',['To prove that the office made no changes during the period','To compare the appearance of the two programs’ publicity','To ensure that every participant misses an appointment'],'Holding vouchers similar while varying scheduling isolates the scheduling contrast. The initial before-after comparison bundles the changes together.')
cross('medium','Text 1\nA fictional editor removes every repeated phrase from a speech, arguing that repetition always wastes time by adding no new factual content. She favors stating each proposition once.\n\nText 2\nA speaker agrees that repetition can be excessive but notes that a recurring phrase can signal the connection among separate examples. Listeners cannot turn back a page during a live speech, so repeated language may help them follow its organization even when it introduces no new fact.','How would the speaker most likely respond to the editor’s rule?','It overlooks an organizational function that repetition can serve for listeners.',['It is wrong because every repetition necessarily introduces a new fact.','It correctly treats all forms of repetition as equally helpful.','It proves that live listeners can reread earlier pages.'],'The speaker identifies a function beyond adding facts and qualifies it as possible, not universal. That directly challenges removing repetition solely for factual redundancy.')
cross('hard','Text 1\nIn a hypothetical discussion, a researcher describes a species as absent from a site because none was detected during a brief visual survey. She argues that additional observation would be unnecessary.\n\nText 2\nAnother researcher notes that the species often remains hidden during the surveyed hours. She recommends repeated surveys using a method suited to its active period. A negative observation, she argues, is more informative when the method would have had a high chance of detecting the species if it were present.','Which principle underlies Text 2’s response?','The strength of evidence from non-detection depends partly on the sensitivity of the observation method.',['Failure to detect a species always proves it is present.','Visual surveys necessarily detect every species at every hour.','Additional observation cannot change an inference about presence.'],'The second researcher evaluates how likely detection would be under presence. This distinguishes a weak negative survey from proof of absence without asserting presence.')
cross('medium','Text 1\nA fictional poet says that an inherited phrase belongs in a new poem exactly as it was received. Changing it, she argues, would break the connection with the voice that first spoke it.\n\nText 2\nAnother poet describes altering an inherited phrase so that it answers a question its original speaker never faced. She retains enough of its rhythm to make the relation audible, treating transformation as one way a voice can continue in a changed setting rather than disappear.','What issue is central to the poets’ disagreement?','Whether continuity with an inherited voice requires keeping its wording unchanged',['Whether poems can contain phrases heard from other people','Whether rhythm can be heard in spoken language','Whether new poems are written in different settings from old ones.'],'One poet locates continuity in unchanged wording, while the other locates it partly in recognizable transformation. Both acknowledge inherited language.')

assert.equal(readingExtended.length,64)
const counts={}
for(const row of readingExtended)counts[row.skill]=(counts[row.skill]??0)+1
assert.equal(Object.keys(counts).length,4)
for(const count of Object.values(counts))assert.equal(count,16)
